func TestCheckURLRefusesNonPublicAddresses(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	e.DNS.Set("mixed.acme.example", "93.184.216.34", "10.0.0.5")
	e.DNS.Set("private.acme.example", "192.168.1.10")
